valid-falloff-troe.text:
description: synthetic nested rate witness
units: {length: cm, quantity: mol, activation-energy: J/mol, pressure: Pa}
phases:
- name: gas
  thermo: ideal-gas
  species: all
  reactions: all
species:
- name: A
  composition: {H: 2}
- name: B
  composition: {H: 2}
reactions:
- equation: A (+M) => B (+M)
  type: falloff
  high-P-rate-constant: {A: 1.0, b: 0.0, Ea: 0.0}
  low-P-rate-constant: {A: 2.0, b: 0.0, Ea: 0.0}
  Troe: {A: 0.5, T3: 1000.0, T1: 10000.0, T2: 5000.0}

